       (SELECT ID FROM INV_LKUP_SERVER_TYPE WHERE CODE = 'APPLICATION'), SYSTIMESTAMP, 'ADMIN'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_SERVER WHERE NAME = 'SRV-APP-01');
INSERT INTO INV_SERVER_AUD (AUDIT_ID, SERVER_ID, NAME, ENVIRONMENT_ID, SERVER_TYPE_ID, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
