       (SELECT ID FROM INV_ENVIRONMENT WHERE CODE = 'PRO'), (SELECT ID FROM INV_LKUP_SERVER_TYPE WHERE CODE = 'APPLICATION'),
       SYSTIMESTAMP, 'ADMIN', 'INSERT', SYSTIMESTAMP, 'ADMIN' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_SERVER_AUD WHERE NAME = 'SRV-APP-01' AND AUD_ACTION = 'INSERT');

