-- Dos filas de INV_SYSTEM (servidor d'aplicacions), una per SIVAP i una altra per PACES, totes
-- dues contra el mateix servidor catalogat SRV-APP-01. Nomes SIVAP te tambe una fila de
-- INV_DATABASE (servidor SRV-BD-01) - PACES es deliberadament "sistema sense BD".
INSERT INTO INV_SYSTEM (ID, SERVER_ID, INSTANCE, PORT, VERSION, DESCRIPTION, CREATED_AT, CREATED_BY)
SELECT INV_SYSTEM_SEQ.nextval, (SELECT ID FROM INV_SERVER WHERE NAME = 'SRV-APP-01'),
       'sivap-prod-01', 8080, 'Spring Boot 3.2.5', 'Servidor d''aplicacions principal de SIVAP', SYSTIMESTAMP, 'ADMIN'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_SYSTEM WHERE INSTANCE = 'sivap-prod-01');
INSERT INTO INV_SYSTEM_AUD (AUDIT_ID, SYSTEM_ID, SERVER_ID, INSTANCE, PORT, VERSION, DESCRIPTION, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_SYSTEM_AUD_SEQ.nextval, (SELECT ID FROM INV_SYSTEM WHERE INSTANCE = 'sivap-prod-01'), (SELECT ID FROM INV_SERVER WHERE NAME = 'SRV-APP-01'),
       'sivap-prod-01', 8080, 'Spring Boot 3.2.5', 'Servidor d''aplicacions principal de SIVAP', SYSTIMESTAMP, 'ADMIN', 'INSERT', SYSTIMESTAMP, 'ADMIN' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_SYSTEM_AUD WHERE INSTANCE = 'sivap-prod-01' AND AUD_ACTION = 'INSERT');

