INSERT INTO INV_DATABASE_AUD (AUDIT_ID, DATABASE_ID, SERVER_ID, SERVICE, PORT, DATABASE_TYPE, DESCRIPTION, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_DATABASE_AUD_SEQ.nextval, (SELECT ID FROM INV_DATABASE WHERE SERVICE = 'SIVAP_PROD'), (SELECT ID FROM INV_SERVER WHERE NAME = 'SRV-BD-01'),
       'SIVAP_PROD', 1521, (SELECT ID FROM INV_DATABASE_VENDOR WHERE NAME = 'Oracle'), 'Base de dades Oracle dedicada de SIVAP', SYSTIMESTAMP, 'ADMIN', 'INSERT', SYSTIMESTAMP, 'ADMIN' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_DATABASE_AUD WHERE SERVICE = 'SIVAP_PROD' AND AUD_ACTION = 'INSERT');

-- Este fichero carga datos desde cero (sin filas legadas de antes de que existieran las columnas
-- DIR3_VALIDATION_ID/APP_DEVELOPMENT_ID), asi que no hace falta ningun backfill: cada INSERT de
-- INV_APP_RESPONSIBLE/INV_APP_AUTHORIZED mas abajo ya fija su propio DIR3_VALIDATION_ID (via
-- INV_DIR3_VALIDATION_SEQ) en el mismo INSERT, y el de INV_APP_WEB_CONTEXT fija su propio
-- APP_DEVELOPMENT_ID igual (join directo con INV_APP_DEVELOPMENT). El endurecimiento a NOT NULL de
-- ambas columnas vive en 35_invai_1.0.5_harden_not_null_ddl.sql (es DDL, no DML) y puede ejecutarse
-- directamente despues de este fichero sin ningun paso previo.

INSERT INTO INV_APP_DATA (ID, APPLICATION_ID, USE_OPEN_DATA_URL, USE_REUSE_URL, CREATED_AT, CREATED_BY)
SELECT INV_APP_DATA_SEQ.nextval, a.APP_APPLICATION_ID, 0, 0, SYSTIMESTAMP, 'MIGRATION'
FROM INV_APPLICATION a
WHERE NOT EXISTS (SELECT 1 FROM INV_APP_DATA od WHERE od.APPLICATION_ID = a.APP_APPLICATION_ID);

INSERT INTO INV_APP_INTEGRATION (ID, APPLICATION_ID, OBSERVATION, CREATED_AT, CREATED_BY)
SELECT INV_APP_INTEGRATION_SEQ.nextval, a.APP_APPLICATION_ID, NULL, SYSTIMESTAMP, 'MIGRATION'
FROM INV_APPLICATION a
WHERE NOT EXISTS (SELECT 1 FROM INV_APP_INTEGRATION ai WHERE ai.APPLICATION_ID = a.APP_APPLICATION_ID);

-- Example "Integracio" connection for APP-001, demoing the External System side (Soffid) rather than
-- another inventory application. soffidUserId/username/roleId below are real-shaped example values
-- (matching what a genuine Soffid SCIM response looks like) but are NOT guaranteed to resolve
-- against any given environment's real Soffid instance - the point is to have a persisted row to
-- exercise the read path, not a working live account.
INSERT INTO INV_EXTERNAL_SYSTEM (ID, NAME, COMPANY_ID, CREATED_AT, CREATED_BY)
SELECT INV_EXTERNAL_SYSTEM_SEQ.nextval, 'Soffid', (SELECT ID FROM INV_COMPANY WHERE NAME = 'Plexus Tech'), SYSTIMESTAMP, 'ADMIN'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_EXTERNAL_SYSTEM WHERE NAME = 'Soffid');

INSERT INTO INV_EXTERNAL_SYSTEM_AUD (AUDIT_ID, EXTERNAL_SYSTEM_ID, NAME, COMPANY_ID, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_EXTERNAL_SYSTEM_AUD_SEQ.nextval,
       (SELECT ID FROM INV_EXTERNAL_SYSTEM WHERE NAME = 'Soffid'),
       'Soffid', (SELECT ID FROM INV_COMPANY WHERE NAME = 'Plexus Tech'), SYSTIMESTAMP, 'ADMIN', 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_EXTERNAL_SYSTEM_AUD WHERE NAME = 'Soffid' AND AUD_ACTION = 'INSERT');

INSERT INTO INV_APP_INTEGRATION_CONN (ID, APP_INTEGRATION_ID, EXTERNAL_SYSTEM_ID, TECHNOLOGY_ID, USERNAME, CREATED_AT, CREATED_BY)
SELECT INV_APP_INTEGRATION_CONN_SEQ.nextval, src.APP_INTEGRATION_ID, src.EXTERNAL_SYSTEM_ID, src.TECHNOLOGY_ID, 'u00004', SYSTIMESTAMP, 'ADMIN'
FROM (
    SELECT ai.ID AS APP_INTEGRATION_ID, es.ID AS EXTERNAL_SYSTEM_ID, t.ID AS TECHNOLOGY_ID
    FROM INV_APPLICATION a
             JOIN INV_APP_INTEGRATION ai ON ai.APPLICATION_ID = a.APP_APPLICATION_ID
             CROSS JOIN (SELECT ID FROM INV_EXTERNAL_SYSTEM WHERE NAME = 'Soffid') es
             CROSS JOIN (SELECT ID FROM INV_TECHNOLOGY WHERE NAME = 'Spring Boot') t
    WHERE a.CODE = 'APP-001'
) src
WHERE NOT EXISTS (
    SELECT 1 FROM INV_APP_INTEGRATION_CONN e
    WHERE e.APP_INTEGRATION_ID = src.APP_INTEGRATION_ID
      AND e.USERNAME = 'u00004'
);

INSERT INTO INV_APP_INTEGRATION_CONN_AUD (AUDIT_ID, APP_INTEGRATION_CONN_ID, APP_INTEGRATION_ID, EXTERNAL_SYSTEM_ID, TECHNOLOGY_ID, USERNAME, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_APP_INTEGR_CONN_AUD_SEQ.nextval,
       e.ID, e.APP_INTEGRATION_ID, e.EXTERNAL_SYSTEM_ID, e.TECHNOLOGY_ID, e.USERNAME, e.CREATED_AT, e.CREATED_BY, 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_INTEGRATION_CONN e
WHERE e.USERNAME = 'u00004'
  AND NOT EXISTS (SELECT 1 FROM INV_APP_INTEGRATION_CONN_AUD ea WHERE ea.APP_INTEGRATION_CONN_ID = e.ID AND ea.AUD_ACTION = 'INSERT');

INSERT INTO INV_APP_INTEGR_REQ_RL (ID, APP_INTEGRATION_CONN_ID, ROLE_ID, CREATED_AT, CREATED_BY)
SELECT INV_APP_INTEGR_REQ_RL_SEQ.nextval, e.ID, ids.ROLE_ID, SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_INTEGRATION_CONN e
         CROSS JOIN (SELECT 26 AS ROLE_ID FROM DUAL UNION ALL SELECT 33 FROM DUAL) ids
WHERE e.USERNAME = 'u00004'
  AND NOT EXISTS (SELECT 1 FROM INV_APP_INTEGR_REQ_RL r WHERE r.APP_INTEGRATION_CONN_ID = e.ID AND r.ROLE_ID = ids.ROLE_ID);

INSERT INTO INV_APP_INTEGR_REQ_RL_AUD (AUDIT_ID, APP_INTEGRATION_REQ_RL_ID, APP_INTEGRATION_CONN_ID, ROLE_ID, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_APP_INTEGR_REQ_RL_AUD_SEQ.nextval, r.ID, r.APP_INTEGRATION_CONN_ID, r.ROLE_ID, r.CREATED_AT, r.CREATED_BY, 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_INTEGR_REQ_RL r
WHERE r.ROLE_ID IN (26, 33)
  AND NOT EXISTS (SELECT 1 FROM INV_APP_INTEGR_REQ_RL_AUD ra WHERE ra.APP_INTEGRATION_REQ_RL_ID = r.ID AND ra.AUD_ACTION = 'INSERT');

