       'A04027006', 0, SYSTIMESTAMP, 'ADMIN' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_APPLICATION WHERE CODE = 'NOTIB');
INSERT INTO INV_APPLICATION_AUD (AUDIT_ID, APP_APPLICATION_ID, CODE, PREFIX, NAME, CATEGORY_ID, SYSTEM_TYPE_ID, FIELD_ID, COMMISSION_ID, STATUS_ID, DESCRIPTION, ADM_UNIT_CODE, DIR3_MISMATCH, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_APPLICATION_AUD_SEQ.nextval, a.APP_APPLICATION_ID, a.CODE, a.PREFIX, a.NAME, a.CATEGORY_ID, a.SYSTEM_TYPE_ID, a.FIELD_ID, a.COMMISSION_ID, a.STATUS_ID, a.DESCRIPTION, a.ADM_UNIT_CODE, a.DIR3_MISMATCH, a.CREATED_AT, a.CREATED_BY, 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM INV_APPLICATION a WHERE a.CODE = 'NOTIB'
  AND NOT EXISTS (SELECT 1 FROM INV_APPLICATION_AUD WHERE CODE = 'NOTIB' AND AUD_ACTION = 'INSERT');

INSERT INTO INV_APPLICATION (APP_APPLICATION_ID, CODE, PREFIX, NAME, CATEGORY_ID, SYSTEM_TYPE_ID, FIELD_ID, COMMISSION_ID, STATUS_ID, DESCRIPTION, ADM_UNIT_CODE, DIR3_MISMATCH, CREATED_AT, CREATED_BY)
SELECT INV_APPLICATION_SEQ.nextval, 'PACES', 'PAC', 'Registre del Pla d''Acció per al Clima i l''Energia Sostenible',
