-- --- AppProvider + AppTechnology (filas hijas de INV_APP_DEVELOPMENT): columna 3 de la matriu
-- (Desenvolupament), asi que solo existen para las mismas 3 aplicaciones que tienen
-- INV_APP_DEVELOPMENT relleno (NOTIB la introduce, PACES/SIVAP la heredan). ---
INSERT INTO INV_APP_PROVIDER (ID, APP_DEVELOPMENT_ID, COMPANY_NAME, ROLE, START_DATE, EXPIRE_DATE, CREATED_AT, CREATED_BY)
SELECT INV_APP_PROVIDER_SEQ.nextval, d.ID, 'Plexus Tech', (SELECT ID FROM INV_ROLE WHERE NAME = 'Proveïdor principal'),
       SYSTIMESTAMP, ADD_MONTHS(SYSTIMESTAMP, 12), SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_DEVELOPMENT d
         JOIN INV_APPLICATION a ON a.APP_APPLICATION_ID = d.APPLICATION_ID
WHERE a.CODE IN ('NOTIB', 'PACES', 'SIVAP')
  AND NOT EXISTS (SELECT 1 FROM INV_APP_PROVIDER ap WHERE ap.APP_DEVELOPMENT_ID = d.ID);

INSERT INTO INV_APP_PROVIDER_AUD (AUDIT_ID, APP_PROVIDER_ID, APP_DEVELOPMENT_ID, COMPANY_NAME, ROLE, START_DATE, EXPIRE_DATE, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_APP_PROVIDER_AUD_SEQ.nextval, ap.ID, ap.APP_DEVELOPMENT_ID, ap.COMPANY_NAME, ap.ROLE, ap.START_DATE, ap.EXPIRE_DATE, ap.CREATED_AT, ap.CREATED_BY, 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_PROVIDER ap
WHERE NOT EXISTS (SELECT 1 FROM INV_APP_PROVIDER_AUD apa WHERE apa.APP_PROVIDER_ID = ap.ID AND apa.AUD_ACTION = 'INSERT');

INSERT INTO INV_APP_TECHNOLOGY (ID, APP_DEVELOPMENT_ID, LAYER, TECHNOLOGY, VERSION, ARCHITECTURE, CREATED_AT, CREATED_BY)
SELECT INV_APP_TECHNOLOGY_SEQ.nextval, d.ID, (SELECT ID FROM INV_LAYER WHERE NAME = 'Backend'),
       (SELECT ID FROM INV_TECHNOLOGY WHERE NAME = 'Spring Boot'), '3.2.5', 'Microserveis REST', SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_DEVELOPMENT d
         JOIN INV_APPLICATION a ON a.APP_APPLICATION_ID = d.APPLICATION_ID
WHERE a.CODE IN ('NOTIB', 'PACES', 'SIVAP')
  AND NOT EXISTS (SELECT 1 FROM INV_APP_TECHNOLOGY at2 WHERE at2.APP_DEVELOPMENT_ID = d.ID);

INSERT INTO INV_APP_TECHNOLOGY_AUD (AUDIT_ID, APP_TECHNOLOGY_ID, APP_DEVELOPMENT_ID, LAYER, TECHNOLOGY, VERSION, ARCHITECTURE, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_APP_TECHNOLOGY_AUD_SEQ.nextval, at2.ID, at2.APP_DEVELOPMENT_ID, at2.LAYER, at2.TECHNOLOGY, at2.VERSION, at2.ARCHITECTURE, at2.CREATED_AT, at2.CREATED_BY, 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_TECHNOLOGY at2
WHERE NOT EXISTS (SELECT 1 FROM INV_APP_TECHNOLOGY_AUD ata WHERE ata.APP_TECHNOLOGY_ID = at2.ID AND ata.AUD_ACTION = 'INSERT');

-- --- Responsables regenerats per a la matriu final (SEDEIB mismatch 5/5, ADIS/RIPEA/NOTIB/PACES
-- match 5/5 amb Juan Ferra, heretant cap avall de l'esquerra a la dreta) ---

INSERT INTO INV_DIR3_VALIDATION (ID, DIR3_STATUS_ID, CREATED_AT, CREATED_BY)
SELECT INV_DIR3_VALIDATION_SEQ.nextval, (SELECT ID FROM INV_LKUP_DIR3_STATUS WHERE CODE = 'NOT_VALIDATED'), SYSTIMESTAMP, 'ADMIN'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_APP_RESPONSIBLE r
             JOIN INV_APP_RESPONSIBLE_AUTHORIZED ara ON ara.ID = r.APP_RESPONSIBLE_AUTHORIZED_ID
             JOIN INV_APPLICATION a ON a.APP_APPLICATION_ID = ara.APPLICATION_ID
             JOIN INV_PERSON p ON p.ID = r.PERSON_ID
             JOIN INV_LKUP_RESPONSIBLE_TYPE rt ON rt.ID = r.RESPONSIBLE_TYPE_ID
    WHERE a.CODE = 'SEDEIB' AND p.EMAIL = 'jferra@dgagric.caib.es' AND rt.NAME = 'Responsable del servei' AND r.DELETED_AT IS NULL);

