SELECT INV_APP_RESPONSIBLE_SEQ.nextval, ara.ID,
       (SELECT ID FROM INV_PERSON WHERE EMAIL = 'jferra@dgagric.caib.es' AND DELETED_AT IS NULL),
       (SELECT ID FROM INV_LKUP_RESPONSIBLE_TYPE WHERE NAME = 'Responsable de la informació'),
       INV_DIR3_VALIDATION_SEQ.currval,
       SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_RESPONSIBLE_AUTHORIZED ara
         JOIN INV_APPLICATION a ON a.APP_APPLICATION_ID = ara.APPLICATION_ID
WHERE a.CODE = 'NOTIB'
  AND NOT EXISTS (SELECT 1 FROM INV_APP_RESPONSIBLE r
             JOIN INV_APP_RESPONSIBLE_AUTHORIZED ara ON ara.ID = r.APP_RESPONSIBLE_AUTHORIZED_ID
             JOIN INV_APPLICATION a ON a.APP_APPLICATION_ID = ara.APPLICATION_ID
             JOIN INV_PERSON p ON p.ID = r.PERSON_ID
             JOIN INV_LKUP_RESPONSIBLE_TYPE rt ON rt.ID = r.RESPONSIBLE_TYPE_ID
    WHERE a.CODE = 'NOTIB' AND p.EMAIL = 'jferra@dgagric.caib.es' AND rt.NAME = 'Responsable de la informació' AND r.DELETED_AT IS NULL);

