INSERT INTO INV_APP_AUTHORIZED_TYPE_LINK (ID, APP_AUTHORIZED_ID, AUTHORIZATION_TYPE_ID, CREATED_AT, CREATED_BY)
SELECT INV_APP_AUTHORIZED_TYPE_LINK_SEQ.nextval, au.ID,
       (SELECT ID FROM INV_AUTHORIZATION_TYPE WHERE NAME = 'Administrador'),
       SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_AUTHORIZED au
         JOIN INV_APP_RESPONSIBLE_AUTHORIZED ara ON ara.ID = au.APP_RESPONSIBLE_AUTHORIZED_ID
         JOIN INV_APPLICATION a ON a.APP_APPLICATION_ID = ara.APPLICATION_ID
WHERE a.CODE = 'NOTIB'
  AND au.PERSON_ID = (SELECT ID FROM INV_PERSON WHERE EMAIL = 'jferra@dgagric.caib.es' AND DELETED_AT IS NULL)
  AND NOT EXISTS (SELECT 1 FROM INV_APP_AUTHORIZED_TYPE_LINK l
             JOIN INV_APP_AUTHORIZED au ON au.ID = l.APP_AUTHORIZED_ID
             JOIN INV_APP_RESPONSIBLE_AUTHORIZED ara ON ara.ID = au.APP_RESPONSIBLE_AUTHORIZED_ID
             JOIN INV_APPLICATION a ON a.APP_APPLICATION_ID = ara.APPLICATION_ID
             JOIN INV_PERSON p ON p.ID = au.PERSON_ID
             JOIN INV_AUTHORIZATION_TYPE t ON t.ID = l.AUTHORIZATION_TYPE_ID
    WHERE a.CODE = 'NOTIB' AND p.EMAIL = 'jferra@dgagric.caib.es' AND t.NAME = 'Administrador' AND au.DELETED_AT IS NULL AND l.DELETED_AT IS NULL);

