-- PACES: cas combinat de responsables (columna 1, 5/5) amb les 3 categories de
-- validacio DIR3 possibles: informacio/servei = Juan Ferra (Personal CAIB, mateix DIR3
-- que l'ADM_UNIT_CODE -> VALIDATED en viu); sistemes/seguretat = Gabriel Gelabert
-- (Personal CAIB, DIR3 diferent, pero validat manualment -> MANUAL, protegit del check
-- en viu); manteniment = Miguel Canet Cortes (personal extern, no Personal CAIB -> NA,
-- fora del check DIR3 per definicio).

INSERT INTO INV_DIR3_VALIDATION (ID, DIR3_STATUS_ID, CREATED_AT, CREATED_BY)
SELECT INV_DIR3_VALIDATION_SEQ.nextval, (SELECT ID FROM INV_LKUP_DIR3_STATUS WHERE CODE = 'VALIDATED'), SYSTIMESTAMP, 'ADMIN'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_APP_RESPONSIBLE r
             JOIN INV_APP_RESPONSIBLE_AUTHORIZED ara ON ara.ID = r.APP_RESPONSIBLE_AUTHORIZED_ID
             JOIN INV_APPLICATION a ON a.APP_APPLICATION_ID = ara.APPLICATION_ID
             JOIN INV_PERSON p ON p.ID = r.PERSON_ID
             JOIN INV_LKUP_RESPONSIBLE_TYPE rt ON rt.ID = r.RESPONSIBLE_TYPE_ID
    WHERE a.CODE = 'PACES' AND p.EMAIL = 'jferra@dgagric.caib.es' AND rt.NAME = 'Responsable de la informació' AND r.DELETED_AT IS NULL);

