-- --- Pestanya "Seguretat": filas hijas de INV_APP_SECURITY. Columna 5 de la matriu (ver cabecera
-- del fichero), introduida unicament a SIVAP: mesura + WebContext validat + rol + classificacio
-- ENS completa. El seu risc es dona d'alta a la seccio dedicada "AppSecurityRisk" mes avall. ---
INSERT INTO INV_APP_SECURITY_MEASURE (ID, APP_SECURITY_ID, TYPE_ID, ENS_REQUIREMENT_ID, DESCRIPTION, CREATED_AT, CREATED_BY)
SELECT INV_APP_SECURITY_MEASURE_SEQ.nextval, s.ID,
       (SELECT ID FROM INV_SECURITY_MEASURE_TYPE WHERE NAME = 'Xifratge'),
       (SELECT ID FROM INV_ENS_REQUIREMENT WHERE NAME = 'Categoria Alta'),
       TO_CLOB('Xifratge de les dades de caràcter personal en repòs.'),
       SYSTIMESTAMP, 'ADMIN'
FROM INV_APPLICATION a
         JOIN INV_APP_SECURITY s ON s.APPLICATION_ID = a.APP_APPLICATION_ID
WHERE a.CODE = 'SIVAP'
  AND NOT EXISTS (SELECT 1 FROM INV_APP_SECURITY_MEASURE m WHERE m.APP_SECURITY_ID = s.ID);

INSERT INTO INV_APP_SECURITY_MEASURE_AUD (AUDIT_ID, APP_SECURITY_MEASURE_ID, APP_SECURITY_ID, TYPE_ID, ENS_REQUIREMENT_ID, DESCRIPTION, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_APP_SECURITY_MEASURE_AUD_SEQ.nextval, m.ID, m.APP_SECURITY_ID, m.TYPE_ID, m.ENS_REQUIREMENT_ID, m.DESCRIPTION, m.CREATED_AT, m.CREATED_BY, 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_SECURITY_MEASURE m
WHERE NOT EXISTS (SELECT 1 FROM INV_APP_SECURITY_MEASURE_AUD ma WHERE ma.APP_SECURITY_MEASURE_ID = m.ID AND ma.AUD_ACTION = 'INSERT');

-- APP_DEVELOPMENT_ID se rellena aqui mismo (join directo con INV_APP_DEVELOPMENT por Application)
-- en vez de dejarlo NULL para un backfill posterior: no hay ninguna fila legada que requiera ese
-- backfill (los datos se cargan desde cero), asi que no tiene sentido mantenerlo.
-- SIVAP (unica aplicacio amb la pestanya "Seguretat" complerta) demostra el cas "contexto web
-- validat": URL + VALIDATED=1 + qui/quan/perque.
INSERT INTO INV_APP_WEB_CONTEXT (ID, APP_SECURITY_ID, APP_DEVELOPMENT_ID, WEB_CONTEXT_ID, FIELD_ID, OBSERVATION, URL, VALIDATED, VALIDATED_AT, VALIDATED_BY, VALIDATED_REASON, CREATED_AT, CREATED_BY)
SELECT INV_APP_WEB_CONTEXT_SEQ.nextval, s.ID, d.ID,
       (SELECT ID FROM INV_WEB_CONTEXT WHERE NAME = 'Intranet'),
       a.FIELD_ID,
       TO_CLOB('Accés restringit al personal del Servei de Desenvolupament Infantil.'),
       'https://intranet.caib.es/sivap',
       1,
       TO_DATE('2026-02-10', 'YYYY-MM-DD'),
       'ADMIN',
       TO_CLOB('Context revisat i validat pel responsable de sistemes.'),
       SYSTIMESTAMP, 'ADMIN'
FROM INV_APPLICATION a
         JOIN INV_APP_SECURITY s ON s.APPLICATION_ID = a.APP_APPLICATION_ID
         JOIN INV_APP_DEVELOPMENT d ON d.APPLICATION_ID = a.APP_APPLICATION_ID
WHERE a.CODE = 'SIVAP'
  AND NOT EXISTS (SELECT 1 FROM INV_APP_WEB_CONTEXT wc WHERE wc.APP_SECURITY_ID = s.ID);

INSERT INTO INV_APP_WEB_CONTEXT_AUD (AUDIT_ID, APP_WEB_CONTEXT_ID, APP_SECURITY_ID, APP_DEVELOPMENT_ID, WEB_CONTEXT_ID, FIELD_ID, OBSERVATION, URL, VALIDATED, VALIDATED_AT, VALIDATED_BY, VALIDATED_REASON, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_APP_WEB_CONTEXT_AUD_SEQ.nextval, wc.ID, wc.APP_SECURITY_ID, wc.APP_DEVELOPMENT_ID, wc.WEB_CONTEXT_ID, wc.FIELD_ID, wc.OBSERVATION, wc.URL, wc.VALIDATED, wc.VALIDATED_AT, wc.VALIDATED_BY, wc.VALIDATED_REASON, wc.CREATED_AT, wc.CREATED_BY, 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_WEB_CONTEXT wc
WHERE NOT EXISTS (SELECT 1 FROM INV_APP_WEB_CONTEXT_AUD wca WHERE wca.APP_WEB_CONTEXT_ID = wc.ID AND wca.AUD_ACTION = 'INSERT');

INSERT INTO INV_APP_ROLE (ID, APP_SECURITY_ID, SECURITY_ROLE_ID, CREATED_AT, CREATED_BY)
SELECT INV_APP_ROLE_SEQ.nextval, s.ID,
