-- Classificacio ENS completa (6 nivells + proveidor identitat + subjeccio ENS + tipus de dades),
-- nomes per a SIVAP (id10), la unica aplicacio amb la pestanya de Seguretat 100% complerta.
INSERT INTO INV_APP_ENS_CLASSIFICATION (ID, APP_SECURITY_ID, OVERALL_GRADE_LEVEL_ID, IDENTITY_PROVIDER_ID, ENS_SUBJECT_ID, PERSONAL_DATA_PROCESSING_ID, APPROVAL_DATE, CONFIDENTIALITY_LEVEL_ID, INTEGRITY_LEVEL_ID, TRACEABILITY_LEVEL_ID, AVAILABILITY_LEVEL_ID, AUTHENTICITY_LEVEL_ID, CREATED_AT, CREATED_BY)
SELECT INV_APP_ENS_CLASSIFICATION_SEQ.nextval, s.ID,
       (SELECT ID FROM INV_LKUP_SECURITY_LEVEL WHERE NAME = 'Alt'),
       (SELECT ID FROM INV_IDENTITY_PROVIDER WHERE NAME = 'Certificat Digital'),
       (SELECT ID FROM INV_LKUP_ENS_SUBJECT WHERE NAME = 'Sí'),
       (SELECT ID FROM INV_PERSONAL_DATA_PROCESSING WHERE NAME = 'Dades de Salut'),
       TO_DATE('2026-01-15', 'YYYY-MM-DD'),
       (SELECT ID FROM INV_LKUP_SECURITY_LEVEL WHERE NAME = 'Alt'),
       (SELECT ID FROM INV_LKUP_SECURITY_LEVEL WHERE NAME = 'Alt'),
       (SELECT ID FROM INV_LKUP_SECURITY_LEVEL WHERE NAME = 'Mitjà'),
       (SELECT ID FROM INV_LKUP_SECURITY_LEVEL WHERE NAME = 'Mitjà'),
       (SELECT ID FROM INV_LKUP_SECURITY_LEVEL WHERE NAME = 'Alt'),
       SYSTIMESTAMP, 'ADMIN'
FROM INV_APPLICATION a
         JOIN INV_APP_SECURITY s ON s.APPLICATION_ID = a.APP_APPLICATION_ID
WHERE a.CODE = 'SIVAP'
  AND NOT EXISTS (SELECT 1 FROM INV_APP_ENS_CLASSIFICATION ec WHERE ec.APP_SECURITY_ID = s.ID);

INSERT INTO INV_APP_ENS_CLASSIFICATION_AUD (AUDIT_ID, APP_ENS_CLASSIFICATION_ID, APP_SECURITY_ID, OVERALL_GRADE_LEVEL_ID, IDENTITY_PROVIDER_ID, ENS_SUBJECT_ID, PERSONAL_DATA_PROCESSING_ID, APPROVAL_DATE, CONFIDENTIALITY_LEVEL_ID, INTEGRITY_LEVEL_ID, TRACEABILITY_LEVEL_ID, AVAILABILITY_LEVEL_ID, AUTHENTICITY_LEVEL_ID, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_APP_ENS_CLASSIFICATION_AUD_SEQ.nextval, ec.ID, ec.APP_SECURITY_ID, ec.OVERALL_GRADE_LEVEL_ID, ec.IDENTITY_PROVIDER_ID, ec.ENS_SUBJECT_ID, ec.PERSONAL_DATA_PROCESSING_ID, ec.APPROVAL_DATE, ec.CONFIDENTIALITY_LEVEL_ID, ec.INTEGRITY_LEVEL_ID, ec.TRACEABILITY_LEVEL_ID, ec.AVAILABILITY_LEVEL_ID, ec.AUTHENTICITY_LEVEL_ID, ec.CREATED_AT, ec.CREATED_BY, 'INSERT', SYSTIMESTAMP, 'ADMIN'
