WHERE NOT EXISTS (SELECT 1 FROM INV_APP_ENS_CLASSIFICATION_AUD eca WHERE eca.APP_ENS_CLASSIFICATION_ID = ec.ID AND eca.AUD_ACTION = 'INSERT');

-- --- AppResponsible + Dir3Validation (one per assignment). Columna 1 de la matriu (ver header del
-- fichero): nomes s'utilitzen els 5 tipus de responsable originals (Informacio/Servei/Sistemes/
-- Seguretat/Manteniment).
--   1 INVAI    - 0/5 tipus (cap responsable).
--   2 PORTAFIB - 1/5 (Responsable de la informacio = Gabriel Gelabert, DIR3 real coincideix -> match).
--   3 SEDEIB   - 5/5, tots Juan Ferra (DIR3 real NO coincideix amb l'ADM_UNIT_CODE de SEDEIB)
--                -> mismatch; DIR3_MISMATCH tambe sembrat a 1 a la propia Application.
--   4 ADIS, 5 RIPEA, 6 NOTIB, 7 PACES - 5/5, combinant les 3 categories de validacio DIR3:
--                Informacio/Servei = Juan Ferra (ADM_UNIT_CODE forçat a A04027006, coincideix amb
--                el seu DIR3 real -> VALIDATED en viu); Sistemes/Seguretat = Gabriel Gelabert
--                (DIR3 diferent, pero validat manualment -> MANUAL); Manteniment = Miguel Canet
--                Cortes (personal extern, no Personal CAIB -> NA, fora del check DIR3). L'autoritzat
--                de les 4 aplicacions es tambe Juan Ferra (match).
--   8 SIVAP    - 5/5, mixant 2 de les 3 categories anteriors (sense el cas extern): Responsable de
--                la informacio = Juan Ferra (DIR3 real coincideix -> VALIDATED en viu), i els 4 tipus
--                restants + el sol Autoritzat = Gabriel Gelabert (el seu DIR3 real, A04027054, NO
--                coincideix amb el de SIVAP -> es força a MANUAL en lloc de deixar-ho en viu).
-- Cap responsable/autoritzat Personal CAIB d'aquest fitxer es una identitat ficticia: tots son Juan
-- Ferra o Gabriel Gelabert (usuaris reals de Soffid), excepte Miguel Canet Cortes (Responsable
-- manteniment a ADIS/RIPEA/NOTIB/PACES), que es deliberadament l'unica persona no-Personal-CAIB,
-- fora del check DIR3 per definicio (estat NA). ---

INSERT INTO INV_DIR3_VALIDATION (ID, DIR3_STATUS_ID, CREATED_AT, CREATED_BY)
SELECT INV_DIR3_VALIDATION_SEQ.nextval, (SELECT ID FROM INV_LKUP_DIR3_STATUS WHERE CODE = 'NOT_VALIDATED'), SYSTIMESTAMP, 'ADMIN'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_APP_RESPONSIBLE r
             JOIN INV_APP_RESPONSIBLE_AUTHORIZED ara ON ara.ID = r.APP_RESPONSIBLE_AUTHORIZED_ID
             JOIN INV_APPLICATION a ON a.APP_APPLICATION_ID = ara.APPLICATION_ID
             JOIN INV_PERSON p ON p.ID = r.PERSON_ID
             JOIN INV_LKUP_RESPONSIBLE_TYPE rt ON rt.ID = r.RESPONSIBLE_TYPE_ID
    WHERE a.CODE = 'SEDEIB' AND p.EMAIL = 'jferra@dgagric.caib.es' AND rt.NAME = 'Responsable de la informació' AND r.DELETED_AT IS NULL);

INSERT INTO INV_DIR3_VALIDATION_AUD (AUDIT_ID, DIR3_VALIDATION_ID, DIR3_STATUS_ID, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_DIR3_VALIDATION_AUD_SEQ.nextval, INV_DIR3_VALIDATION_SEQ.currval, (SELECT ID FROM INV_LKUP_DIR3_STATUS WHERE CODE = 'NOT_VALIDATED'), SYSTIMESTAMP, 'ADMIN', 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM INV_APP_RESPONSIBLE r
             JOIN INV_APP_RESPONSIBLE_AUTHORIZED ara ON ara.ID = r.APP_RESPONSIBLE_AUTHORIZED_ID
             JOIN INV_APPLICATION a ON a.APP_APPLICATION_ID = ara.APPLICATION_ID
             JOIN INV_PERSON p ON p.ID = r.PERSON_ID
             JOIN INV_LKUP_RESPONSIBLE_TYPE rt ON rt.ID = r.RESPONSIBLE_TYPE_ID
    WHERE a.CODE = 'SEDEIB' AND p.EMAIL = 'jferra@dgagric.caib.es' AND rt.NAME = 'Responsable de la informació' AND r.DELETED_AT IS NULL);

