-- --- AppSecurityRisk: columna 5 de la matriu (Seguretat), introduida unicament a SIVAP, l'unica
-- aplicacio amb classificacio Alta donada la sensibilitat de les dades que tracta (desenvolupament
-- infantil i atencio primerenca). FIELD_ID es pren del propi Field de l'aplicacio. ---
INSERT INTO INV_APP_SECURITY_RISK (ID, APP_SECURITY_ID, LEVEL_ID, DESCRIPTION, FIELD_ID, CREATED_AT, CREATED_BY)
SELECT INV_APP_SECURITY_RISK_SEQ.nextval,
       (SELECT ID FROM INV_APP_SECURITY WHERE APPLICATION_ID = (SELECT APP_APPLICATION_ID FROM INV_APPLICATION WHERE CODE = 'SIVAP')),
       (SELECT ID FROM INV_LKUP_SECURITY_LEVEL WHERE NAME = 'Alt'),
       TO_CLOB('Risc de tractament indegut de dades de salut i desenvolupament infantil de menors.'),
       (SELECT FIELD_ID FROM INV_APPLICATION WHERE CODE = 'SIVAP'),
       SYSTIMESTAMP, 'ADMIN'
FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM INV_APP_SECURITY_RISK
    WHERE APP_SECURITY_ID = (SELECT ID FROM INV_APP_SECURITY WHERE APPLICATION_ID = (SELECT APP_APPLICATION_ID FROM INV_APPLICATION WHERE CODE = 'SIVAP'))
);

INSERT INTO INV_APP_SECURITY_RISK_AUD (AUDIT_ID, APP_SECURITY_RISK_ID, APP_SECURITY_ID, LEVEL_ID, DESCRIPTION, FIELD_ID, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_APP_SECURITY_RISK_AUD_SEQ.nextval, sr.ID, sr.APP_SECURITY_ID, sr.LEVEL_ID, sr.DESCRIPTION, sr.FIELD_ID, sr.CREATED_AT, sr.CREATED_BY, 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_SECURITY_RISK sr
WHERE sr.APP_SECURITY_ID = (SELECT ID FROM INV_APP_SECURITY WHERE APPLICATION_ID = (SELECT APP_APPLICATION_ID FROM INV_APPLICATION WHERE CODE = 'SIVAP'))
  AND NOT EXISTS (SELECT 1 FROM INV_APP_SECURITY_RISK_AUD sra WHERE sra.APP_SECURITY_RISK_ID = sr.ID AND sra.AUD_ACTION = 'INSERT');

-- --- Integration example for SIVAP -> PORTAFIB (SIVAP envia expedients a signar via Porta
-- Firmes): columna 6 de la matriu (Integracions), introduida unicament a SIVAP, l'unica
-- aplicacio "completa" que ademes demostra el cas "integracio inclosa". ---
INSERT INTO INV_APP_INTEGRATION_CONN (ID, APP_INTEGRATION_ID, APPLICATION_ID, TECHNOLOGY_ID, USERNAME, CREATED_AT, CREATED_BY)
SELECT INV_APP_INTEGRATION_CONN_SEQ.nextval, src.APP_INTEGRATION_ID, src.PORTAFIB_APPLICATION_ID, src.TECHNOLOGY_ID, 'u00456', SYSTIMESTAMP, 'ADMIN'
FROM (
    SELECT ai.ID AS APP_INTEGRATION_ID, portafib.APP_APPLICATION_ID AS PORTAFIB_APPLICATION_ID, t.ID AS TECHNOLOGY_ID
    FROM INV_APPLICATION a
             JOIN INV_APP_INTEGRATION ai ON ai.APPLICATION_ID = a.APP_APPLICATION_ID
             CROSS JOIN (SELECT APP_APPLICATION_ID FROM INV_APPLICATION WHERE CODE = 'PORTAFIB') portafib
             CROSS JOIN (SELECT ID FROM INV_TECHNOLOGY WHERE NAME = 'Spring Boot') t
    WHERE a.CODE = 'SIVAP'
) src
WHERE NOT EXISTS (
    SELECT 1 FROM INV_APP_INTEGRATION_CONN e
    WHERE e.APP_INTEGRATION_ID = src.APP_INTEGRATION_ID
      AND e.USERNAME = 'u00456'
);

INSERT INTO INV_APP_INTEGRATION_CONN_AUD (AUDIT_ID, APP_INTEGRATION_CONN_ID, APP_INTEGRATION_ID, APPLICATION_ID, TECHNOLOGY_ID, USERNAME, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_APP_INTEGR_CONN_AUD_SEQ.nextval,
       e.ID, e.APP_INTEGRATION_ID, e.APPLICATION_ID, e.TECHNOLOGY_ID, e.USERNAME, e.CREATED_AT, e.CREATED_BY, 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_INTEGRATION_CONN e
WHERE e.USERNAME = 'u00456'
  AND NOT EXISTS (SELECT 1 FROM INV_APP_INTEGRATION_CONN_AUD ea WHERE ea.APP_INTEGRATION_CONN_ID = e.ID AND ea.AUD_ACTION = 'INSERT');

INSERT INTO INV_APP_INTEGR_REQ_RL (ID, APP_INTEGRATION_CONN_ID, ROLE_ID, CREATED_AT, CREATED_BY)
SELECT INV_APP_INTEGR_REQ_RL_SEQ.nextval, e.ID, ids.ROLE_ID, SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_INTEGRATION_CONN e
         CROSS JOIN (SELECT 63 AS ROLE_ID FROM DUAL UNION ALL SELECT 78 FROM DUAL) ids
WHERE e.USERNAME = 'u00456'
  AND NOT EXISTS (SELECT 1 FROM INV_APP_INTEGR_REQ_RL r WHERE r.APP_INTEGRATION_CONN_ID = e.ID AND r.ROLE_ID = ids.ROLE_ID);

INSERT INTO INV_APP_INTEGR_REQ_RL_AUD (AUDIT_ID, APP_INTEGRATION_REQ_RL_ID, APP_INTEGRATION_CONN_ID, ROLE_ID, CREATED_AT, CREATED_BY, AUD_ACTION, AUDIT_DATE, AUDIT_USER)
SELECT INV_APP_INTEGR_REQ_RL_AUD_SEQ.nextval, r.ID, r.APP_INTEGRATION_CONN_ID, r.ROLE_ID, r.CREATED_AT, r.CREATED_BY, 'INSERT', SYSTIMESTAMP, 'ADMIN'
FROM INV_APP_INTEGR_REQ_RL r
WHERE r.ROLE_ID IN (63, 78)
  AND NOT EXISTS (SELECT 1 FROM INV_APP_INTEGR_REQ_RL_AUD ra WHERE ra.APP_INTEGRATION_REQ_RL_ID = r.ID AND ra.AUD_ACTION = 'INSERT');

COMMIT;
